function emitDiff(a, aLo0, aHi0, b, bLo0, bHi0, ops) {
  // Stack items: [type, ...]. type 0: range to diff; 1: equal run; 2: delete run; 3: insert run
  const stack = [[0, aLo0, aHi0, bLo0, bHi0]];
  while (stack.length > 0) {
    const item = stack.pop();
    if (item[0] === 1) { // equal run a[i..j)
      for (let i = item[1]; i < item[2]; i++) ops.push({ op: 'equal', line: a[i] });
      continue;
    }
    if (item[0] === 2) {
      for (let i = item[1]; i < item[2]; i++) ops.push({ op: 'delete', line: a[i] });
      continue;
    }
    if (item[0] === 3) {
      for (let i = item[1]; i < item[2]; i++) ops.push({ op: 'insert', line: b[i] });
      continue;
    }
    let [, aLo, aHi, bLo, bHi] = item;
    // trim common prefix
    let p = 0;
    const n0 = aHi - aLo, m0 = bHi - bLo;
    const lim = Math.min(n0, m0);
    while (p < lim && a[aLo + p] === b[bLo + p]) p++;
    let q = 0;
    while (q < lim - p && a[aHi - 1 - q] === b[bHi - 1 - q]) q++;
    const aLo2 = aLo + p, aHi2 = aHi - q, bLo2 = bLo + p, bHi2 = bHi - q;
    const n = aHi2 - aLo2, m = bHi2 - bLo2;
    // Push in reverse emission order: prefix-eq, left, middle-eq, right, suffix-eq
    if (q > 0) stack.push([1, aHi2, aHi]);
    if (n === 0 && m === 0) {
      // nothing
    } else if (n === 0) {
      stack.push([3, bLo2, bHi2]);
    } else if (m === 0) {
      stack.push([2, aLo2, aHi2]);
    } else {
      const [x, y, u, v] = middleSnake(a, aLo2, aHi2, b, bLo2, bHi2);
      // emission: diff(left), equal(snake), diff(right)
      if (u < n || v < m) stack.push([0, aLo2 + u, aHi2, bLo2 + v, bHi2]);
      if (u > x) stack.push([1, aLo2 + x, aLo2 + u]);
      if (x > 0 || y > 0) stack.push([0, aLo2, aLo2 + x, bLo2, bLo2 + y]);
    }
    if (p > 0) stack.push([1, aLo, aLo2]);
  }
}
