function unifiedHunks(a, b, options) {
  const { context = 3 } = options || {};
  if (!Number.isInteger(context) || context < 0) throw new Error('context must be a nonnegative integer');
  const ops = diffLines(a, b);
  // find changed op indices
  const n = ops.length;
  // compute consumed-old before each op index? We need per-hunk consumed counts.
  // Find runs of non-equal ops
  const runs = [];
  let i = 0;
  while (i < n) {
    if (ops[i].op === 'equal') { i++; continue; }
    let j = i;
    while (j < n && ops[j].op !== 'equal') j++;
    runs.push([i, j - 1]); // inclusive
    i = j;
  }
  if (runs.length === 0) return [];
  // merge runs with gap <= 2*context
  const merged = [runs[0].slice()];
  for (let r = 1; r < runs.length; r++) {
    const prev = merged[merged.length - 1];
    const gap = runs[r][0] - prev[1] - 1; // number of equal ops between
    if (gap <= 2 * context) prev[1] = runs[r][1];
    else merged.push(runs[r].slice());
  }
  // prefix counts: consumedOld[k] = # equal+delete among ops[0..k)
  const consumedOld = new Int32Array(n + 1);
  const consumedNew = new Int32Array(n + 1);
  for (let k = 0; k < n; k++) {
    consumedOld[k+1] = consumedOld[k] + (ops[k].op !== 'insert' ? 1 : 0);
    consumedNew[k+1] = consumedNew[k] + (ops[k].op !== 'delete' ? 1 : 0);
  }
  const hunks = [];
  for (const [rs, re] of merged) {
    const s = Math.max(0, rs - context);
    const e = Math.min(n - 1, re + context);
    let oldCount = 0, newCount = 0;
    const lines = [];
    for (let k = s; k <= e; k++) {
      const op = ops[k];
      if (op.op === 'equal') { lines.push(' ' + op.line); oldCount++; newCount++; }
      else if (op.op === 'delete') { lines.push('-' + op.line); oldCount++; }
      else { lines.push('+' + op.line); newCount++; }
    }
    const oldBefore = consumedOld[s], newBefore = consumedNew[s];
    hunks.push({
      oldStart: oldCount > 0 ? oldBefore + 1 : oldBefore,
      oldLines: oldCount,
      newStart: newCount > 0 ? newBefore + 1 : newBefore,
      newLines: newCount,
      lines,
    });
  }
  return hunks;
}
