      const c = line[0];
      if (c === ' ') { oldCount++; newCount++; }
      else if (c === '-') oldCount++;
      else if (c === '+') newCount++;
      else fail();
    }
    if (oldCount !== oldLines || newCount !== newLines) fail();
    const oldPos = oldLines > 0 ? oldStart - 1 : oldStart;
    const newPos = newLines > 0 ? newStart - 1 : newStart;
    if (oldPos < cursor) fail(); // overlapping / unordered
