function normalizeOps(ops) {
  const out = [];
  let i = 0;
  const n = ops.length;
  while (i < n) {
    const op = ops[i];
    if (op.op === 'equal') { out.push(op); i++; continue; }
    let j = i;
    while (j < n && ops[j].op !== 'equal') j++;
    // emit deletes then inserts, preserving relative order
    for (let k = i; k < j; k++) if (ops[k].op === 'delete') out.push(ops[k]);
    for (let k = i; k < j; k++) if (ops[k].op === 'insert') out.push(ops[k]);
    i = j;
  }
  return out;
}
```

