function mod(k, z) {
  return ((k % z) + z) % z;
}

/**
 * Find a middle snake for a[aLo..aHi) vs b[bLo..bHi) (both nonempty, with no
 * common first/last line required by the caller). Returns [x, y, u, v] such
 * that the snake matches a[aLo + x .. aLo + u) against b[bLo + y .. bLo + v)
 * and the edit distance splits about evenly across the two outer pieces.
 */
function middleSnake(a, aLo, aHi, b, bLo, bHi) {
  const N = aHi - aLo;
  const M = bHi - bLo;
  const L = N + M;
  const w = N - M;
  const Z = 2 * Math.min(N, M) + 2;
  const g = new Int32Array(Z); // forward furthest-reaching x per diagonal
  const p = new Int32Array(Z); // reverse furthest-reaching x per diagonal
